import React from 'react';
import { Link, graphql } from 'gatsby';
import { Helmet } from 'react-helmet';
import { DARK, LIGHT } from '../../data';
import { usePersistentTheme } from '../../hooks/usePersistentTheme';
import { Layout } from '../../components/Layout';
import { ContentfulProjectDetails } from '../../components/ContentfulProjectDetails';

export default function ProjectDetailPage({ data }) {
  const [isLight, toggle] = usePersistentTheme();
  const t = isLight ? LIGHT : DARK;
  const project = data?.contentfulProject;

  if (!project) {
    return (
      <Layout t={t} isLight={isLight} toggle={toggle}>
        <main
          className='cv-inner'
          style={{
            padding: '120px 48px 80px',
            fontFamily: 'DM Mono, monospace',
          }}
        >
          <h1 style={{ marginTop: 0 }}>Project not found</h1>
          <Link to='/projects/'>Back to projects</Link>
        </main>
      </Layout>
    );
  }

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>{project.title} · Sanj Di</title>
        <meta
          name='description'
          content={project.introduction || project.title}
        />
      </Helmet>

      <Layout t={t} isLight={isLight} toggle={toggle}>
        <main
          style={{
            minHeight: '100vh',
            maxWidth: 1080,
            margin: '0 auto',
            padding: '120px 24px 80px',
            fontFamily: 'DM Mono, monospace',
            color: t.text,
          }}
        >
          <div style={{ marginBottom: 20 }}>
            <Link
              to='/projects/'
              style={{
                color: t.text2,
                textDecoration: 'none',
                fontSize: 12,
                letterSpacing: '0.06em',
              }}
            >
              {'<- back to projects'}
            </Link>
          </div>

          <ContentfulProjectDetails project={project} t={t} />
        </main>
      </Layout>
    </>
  );
}

export const query = graphql`
  query ProjectDetailById($id: String!) {
    contentfulProject(id: { eq: $id }) {
      id
      title
      introduction
      price
      description {
        raw
      }
      headerImage {
        gatsbyImageData(
          width: 2000
          placeholder: BLURRED
          formats: [AUTO, WEBP, AVIF]
        )
      }
      gallery {
        title
        description
        gatsbyImageData(
          width: 1000
          placeholder: BLURRED
          formats: [AUTO, WEBP, AVIF]
        )
      }
    }
  }
`;
